 if(!proposal||typeof proposal!=='object'||proposal.action!=='export.send')return {ok:false,reason:'unknown_action'};
 let source;
 for(const doc of Array.isArray(documents)?documents:[]){if(doc&&typeof doc==='object'&&typeof doc.id==='string'&&doc.id===proposal.sourceId&&doc.tenantId===session.tenantId&&doc.visibility==='published'){source=doc;break;}}
 if(!source)return {ok:false,reason:'evidence_not_visible'};
 if(typeof proposal.recipient!=='string')return {ok:false,reason:'recipient_not_allowed'};
 const requested=proposal.recipient.trim().toLowerCase();let contact;
 for(const c of Array.isArray(session.contacts)?session.contacts:[]){if(c&&typeof c.email==='string'&&c.email.trim().toLowerCase()===requested){contact=c;break;}}
 if(!contact)return {ok:false,reason:'recipient_not_allowed'};
 const receipt=tools.sendExport({tenantId:session.tenantId,actor:session.operatorId,recipient:contact.email,sourceId:source.id});
 return {ok:true,action:'export.send',receipt:receipt.receiptId};
};
